import re,glob,os
pat=re.compile(r'(the Lean|in Lean|Lean proof|Lean body|Lean definition|Lean declaration|Lean file|Lean target|Lean side|Lean-side|Lean encoding|sorry|axiom-clean|tactic|typeclass|heartbeat|\bsimp\b|\brfl\b|defeq|scaffold|stub|placeholder|TODO|omitted here|sketch|hand-wave|deferred|not yet|currently|iteration|run 00|iter-)')
for f in sorted(glob.glob('*.tex')):
    L=open(f).read().split('\n')
    inp=False; body=[]; start=0
    for i,l in enumerate(L):
        if '\\begin{proof}' in l: inp=True; start=i+1; body=[]; continue
        if '\\end{proof}' in l and inp:
            inp=False
            txt=[(start+k, b) for k,b in enumerate(body) if not b.strip().startswith('%')]
            joined=' '.join(b for _,b in txt).strip()
            plain=re.sub(r'\\(leanok|uses\{[^}]*\}|notready|mathlibok|label\{[^}]*\})','',joined).strip()
            hits=[(ln,b.strip()) for ln,b in txt if pat.search(b) and not b.strip().startswith('%')]
            if len(plain)<170 or hits:
                print(f"### {f}:{start}-{i+1}  len={len(plain)}")
                if len(plain)<170: print("   SHORT:", plain[:230])
                for ln,b in hits[:3]: print(f"   {ln}: {b[:160]}")
            body=[]
            continue
        if inp: body.append(l)
EOF

